@Route(path = PagePath.PAGE_GLASSES_CALL_RECORD)
class GlassesCallRecordActivity :
    BaseActivity<GlassesAudioViewModel, ActivityGlassesCallRecordBinding>() {

    private var mReNameDialog: BaseCommonDialog? = null
    private var mSelectMorePopup: PopupWindow? = null

    private val mAdapter = GlassesAudioEditAdapter2()

    private val mHandler = Handler(Looper.getMainLooper())

    private var isRecording = false

    private val mScope = MainScope()

    private val callback = object : OnEventListener {
        override fun onEvent(type: EventType, code: Int, data: Any?) {
            when (type) {
                EventType.TYPE_CALL_RECORD_CONTROL_SUPPORT -> {
                    runOnUiThread { mBinding.clRecordLayout.isVisible = (code == 1) }
                }

                EventType.TYPE_GLASSES_CALL_RECORD -> {
                    handlerCallRecordStatus(code)
                }

                EventType.TYPE_DEVICE_STATE -> {
                    if (code == DeviceState.STATE_CONNECT_FAIL || code == DeviceState.STATE_NO_CONNECTION) {
                        handlerCallRecordStatus(1)
                    }
                }

                else -> {}
            }
        }
    }

    private var startCallTimeout = Runnable {
        LogUtils.d(TAG, "startCall timeout")
        runOnUiThread {
            dismissLoading()
            refreshCallRecordStart()
        }
    }

    private var endCallTimeout = Runnable {
        LogUtils.d(TAG, "endCall timeout")
        runOnUiThread {
            dismissLoading()
            refreshCallRecordEnd()
            ToastUtils.showToast(getString(R1.string.string_g_call_record_tip8))
        }
    }

    private val callCallback = object : CallRecordMgr.Callback {
        override fun onStart() {
            mReNameDialog?.dismiss()
            mViewModel.getList(2)
        }

        override fun onCallData(data: ByteArray) {
        }

        override fun onEnd() {
            mReNameDialog?.dismiss()
            mViewModel.getList(2)
        }
    }

    override fun initViews() {
        super.initViews()
        mBinding.titleBar.setCallBack(object : MyTitleBar.OnTopBarCallBack {
            override fun onClickBack() {
                finish()
            }

            override fun onClickMenu() {
                super.onClickMenu()
                if (!mBinding.titleBar.ivMenu.isVisible) return
                val bundle =
                    bundleOf("position" to 2, "title" to getString(R1.string.call_record_title))
                Navigator.start(context, GlassesAudioEditActivity::class.java, bundle, 999)
            }
        })
        mBinding.rvContent.addItemDecoration(LinearItemDecoration(UIHelper.dp2px(12f)))
        mBinding.rvContent.adapter = mAdapter
        mAdapter.setOnItemClickListener { _, _, position ->
            val bean = mAdapter.data[position]
            if (bean.itemType == GlassesRecordBean.TYPE_CALLING) {
                Navigator.start(context, CallRecordSelectActivity::class.java, Bundle().apply {
                    putSerializable("callRecordBean", bean.data as CallRecordBean)
                })
            } else if (bean.itemType == GlassesRecordBean.TYPE_CALL) {
                Navigator.start(context, CallRecordActivity::class.java, Bundle().apply {
                    putSerializable("callRecordBean", bean.data as CallRecordBean)
                }, 999)
            }
        }
        mAdapter.setOnItemChildClickListener { _, view, position ->
            when (view.id) {
                R.id.iv_more -> {
                    showMoreOptionsDialog(view, position)
                }
            }
        }
        mBinding.btnRecord.setOnClickListener {
            if (isRecording) {
                mHandler.postDelayed(endCallTimeout, 8000)
                refreshCallRecordEnding()
                CallRecordMgr.handlerCallingToSaving()
                ServiceManager.getDeviceService()
                    .sendData(GlassesOrder.sendCallRecordControl(false))
            } else {
                mHandler.postDelayed(startCallTimeout, 8000)
                ServiceManager.getDeviceService().sendData(GlassesOrder.sendCallRecordControl(true))
                showLoading()
            }
        }
    }

    override fun initData() {
        super.initData()
        ServiceManager.getDeviceService().registerListener(
            callback,
            EventType.TYPE_CALL_RECORD_CONTROL_SUPPORT,
            EventType.TYPE_GLASSES_CALL_RECORD,
            EventType.TYPE_DEVICE_STATE
        )
    }

    override fun loadData() {
        super.loadData()
        CallRecordMgr.registerCallback(this, callCallback)
        val notConvertList = CallRecordMgr.getCacheList().filter { !it.isConvert }
        if (notConvertList.isNotEmpty()) {
            // 处理上次未收到完成指令的录音数据
            LoadingDialog.showLoading(context)
            handleUnfinished(notConvertList)
            refreshCallRecordEnd()
        } else {
            mViewModel.getList(2)
            refreshCallRecordStart()
        }
        ServiceManager.getDeviceService().sendData(GlassesOrder.sendCallRecordControlSupport())
    }

    override fun addObserve() {
        super.addObserve()
        mViewModel.dataList.observe(this) { list ->
            if (CollectionUtils.isEmpty(list)) {
                mBinding.rvContent.visibility = View.GONE
                mBinding.llEmpty.visibility = View.VISIBLE
                mBinding.titleBar.ivMenu.visibility = View.GONE
                mBinding.ivTopBg.visibility = View.VISIBLE
            } else {
                mBinding.rvContent.visibility = View.VISIBLE
                mBinding.llEmpty.visibility = View.GONE
                mBinding.titleBar.ivMenu.visibility = View.VISIBLE
                mBinding.ivTopBg.visibility = View.GONE

                mAdapter.refreshCacheName(GlassesFileSyncMgr.getSoundCache())
                mAdapter.setList(list)
            }
        }
    }

    override fun showLoading() {
        super.showLoading()
        LoadingDialog.showLoading(this)
    }

    override fun dismissLoading() {
        super.dismissLoading()
        LoadingDialog.dismissLoading()
    }

    /**
     * 生成会议选项重命名弹窗
     */
    private fun showMeetReNameDialog(position: Int) {
        val bean = mAdapter.getItem(position)
        if (bean.itemType == GlassesRecordBean.TYPE_CALLING) return
        var path = ""
        var name = ""
        if (bean.itemType == GlassesRecordBean.TYPE_CALL) {
            val bean = bean.data as CallRecordBean
            path = bean.filePath
            name = getName2(bean)
        } else {
            var bean = bean.data as AudioItemBean
            path = bean.file
            name = getName(bean)
        }

        mReNameDialog?.dismiss()
        mReNameDialog = BaseCommonDialog.Builder(this)
            .addContentViewRoot(R.layout.dialog_rename)
            .setGravity(Gravity.CENTER)
            .setCancelTouchOut(false)
            .setBottomLayoutVisible(View.GONE)
            .setTextContentTitle(R.id.et_more_m_name, name)
            .addViewOnclick(R.id.iv_close) {
                mReNameDialog?.dismiss()
            }
            .addViewOnclick(R.id.tv_rename_cancel) {
                mReNameDialog?.dismiss()
            }
            .addViewOnclick(R.id.tv_rename_ok) {
                mReNameDialog?.dismiss()
                val editTextView =
                    mReNameDialog!!.mBinding.commonContentArea.findViewById<EditText>(R.id.et_more_m_name)
                val reName = editTextView.text.toString().trim()
                if (!TextUtils.isEmpty(reName)) {
                    GlassesFileSyncMgr.saveSoundName(path, reName)
                    mAdapter.refreshCacheName(GlassesFileSyncMgr.getSoundCache())
                }
                mAdapter.notifyItemChanged(position)
            }
            .builder()
        mReNameDialog?.show()
    }

    private fun getName(item: AudioItemBean): String {
        val cacheName = GlassesFileSyncMgr.getSoundCache()
        val bean = cacheName.find { it.path == item.file }
        return bean?.name ?: item.name
    }

    private fun getName2(item: CallRecordBean): String {
        val cacheName = GlassesFileSyncMgr.getSoundCache()
        val bean = cacheName.find { it.path == item.filePath }
        if (bean != null) return bean.name
        if (!TextUtils.isEmpty(item.bookName)) return item.bookName
        return item.name
    }

    private fun handleUnfinished(list: List<CallRecordBean>) {
        val createTime = CallRecordMgr.getCallIngBean()?.createTime ?: -1
        val newList = list.filter { it.createTime != createTime }
        mScope.launch(Dispatchers.IO) {
            newList.forEach {
                CallRecordMgr.convertFile(it.opusPath, it)
            }
            withContext(Dispatchers.Main) {
                LoadingDialog.dismissLoading()
                mViewModel.getList(2)
            }
        }
    }

    private fun refreshCallRecordStart() {
        isRecording = false
        mBinding.btnRecord.setCardBackgroundColor(
            ContextCompat.getColor(
                this,
                R1.color.color_ff7300
            )
        )
        mBinding.btnRecord.isEnabled = true
        mBinding.tvRecord.text = getString(R1.string.jacket_m_s_t_s)
        mBinding.tvRecord.setTextColor(Color.WHITE)
        mBinding.btnRecordTip.isVisible = true
        mBinding.btnRecordTip.text = getString(R1.string.string_g_call_record_tip9)
    }

    private fun refreshCallRecordEnd() {
        isRecording = true
        mBinding.btnRecord.setCardBackgroundColor(
            ContextCompat.getColor(
                this,
                R1.color.color_ff5858
            )
        )
        mBinding.btnRecord.isEnabled = true
        mBinding.tvRecord.text = getString(R1.string.jacket_m_end_record)
        mBinding.tvRecord.setTextColor(Color.WHITE)
        mBinding.btnRecordTip.isVisible = true
        mBinding.btnRecordTip.text = getString(R1.string.string_g_call_record_tip10)
    }

    private fun refreshCallRecordEnding() {
        isRecording = false
        mBinding.btnRecord.setCardBackgroundColor(
            ContextCompat.getColor(
                this,
                R1.color.color_B3FF7300
            )
        )
        mBinding.btnRecord.isEnabled = false
        mBinding.tvRecord.text = getString(R1.string.string_g_call_record_tip11)
        mBinding.tvRecord.setTextColor(Color.WHITE)
        mBinding.btnRecordTip.isVisible = false
        mBinding.btnRecordTip.text = getString(R1.string.string_g_call_record_tip9)
    }

    private fun  handlerCallRecordStatus(code: Int) {
        runOnUiThread {
            mHandler.removeCallbacks(startCallTimeout)
            mHandler.removeCallbacks(endCallTimeout)
            dismissLoading()
            if (code == 1) {
                refreshCallRecordEnd()
                return@runOnUiThread
            }
            val content = when (code) {
                2,5 -> getString(R1.string.string_g_call_record_tip12)
                3 -> getString(R1.string.string_g_call_record_tip13)
                4 -> getString(R1.string.string_g_call_record_tip14)
                6 -> getString(R1.string.string_g_call_record_tip15)
                else -> ""
            }
            if (!TextUtils.isEmpty(content)) {
                GlassesCommonTipDialog(
                    this@GlassesCallRecordActivity,
                    title = getString(R1.string.tip89),
                    tips = content,
                    btnText = getString(R1.string.string_ok)
                ).show()
            }
            refreshCallRecordStart()
        }
    }

    /**
     * 显示更多选项弹窗
     */
    private fun showMoreOptionsDialog(view: View, position: Int) {
        // 关闭之前的弹窗
        mSelectMorePopup?.dismiss()
        // 使用PopupWindow实现，背景不会变暗
        val popupView = layoutInflater.inflate(R.layout.dialog_audio_more, null)
        mSelectMorePopup = PopupWindow(
            popupView,
            android.view.ViewGroup.LayoutParams.WRAP_CONTENT,
            android.view.ViewGroup.LayoutParams.WRAP_CONTENT,
            true
        )
        // 设置点击外部可关闭
        mSelectMorePopup?.isOutsideTouchable = true
        mSelectMorePopup?.isFocusable = true
        // 设置背景为透明，这样CardView的阴影才能显示
        mSelectMorePopup?.setBackgroundDrawable(android.graphics.drawable.ColorDrawable(Color.TRANSPARENT))
        // 重命名点击事件
        popupView.findViewById<androidx.appcompat.widget.AppCompatTextView>(R.id.tv_rename)
            .setOnClickListener {
                mSelectMorePopup?.dismiss()
                showMeetReNameDialog(position)
            }
        // 分享点击事件
        popupView.findViewById<androidx.appcompat.widget.AppCompatTextView>(R.id.tv_share)
            .setOnClickListener {
                mSelectMorePopup?.dismiss()
                // 实现分享功能
                val item = mAdapter.getItem(position)
                if (item.itemType == GlassesRecordBean.TYPE_RECORD) {
                    val bean = item.data as AudioItemBean
                    ShareUtils.shareSystemFile(context, bean.file)
                } else {
                    val bean = item.data as CallRecordBean
                    ShareUtils.shareSystemFile(context, bean.filePath)
                }
            }
        // 设置弹窗位置
        val location = IntArray(2)
        view.getLocationOnScreen(location)
        mSelectMorePopup?.showAtLocation(
            view,
            Gravity.TOP or Gravity.END,
            UIHelper.dp2px(8F), // 右边距
            location[1] + UIHelper.dp2px(12F) // 顶部距离
        )
    }

    override fun onActivityResult(requestCode: Int, resultCode: Int, data: Intent?) {
        super.onActivityResult(requestCode, resultCode, data)
        if (requestCode == 999 && resultCode == RESULT_OK) {
            mViewModel.getList(2)
        }
    }

    override fun onDestroy() {
        super.onDestroy()
        CallRecordMgr.unregisterCallback(callCallback)
        ServiceManager.getDeviceService().unregisterListener(callback)
        mHandler.removeCallbacksAndMessages(null)
    }
}
